macro_rules! deps {
    () => {
        Pending!();
        PositionFuture!();
        TryFoldFuture!();
        AllFuture!();
        NthFuture!();
        Drain!();
        TryNextFuture!();
        AnyFuture!();
        TryForEachFuture!();
        NextFuture!();
        FindFuture!();
        FindMapFuture!();
    };
}

